component.css:
.apd{position:relative;width:100%;aspect-ratio:3/2;container-type:size;background:transparent;opacity:1;transition:opacity .6s;font-family:Roboto,"Noto Sans","PingFang SC","Microsoft YaHei",sans-serif}
.apd.off{opacity:0}
.apd-scrim{position:absolute;inset:0;background:rgba(0,0,0,.16);opacity:0;transition:opacity .2s}
.apd-scrim.on{opacity:1}
.apd-dlg{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(.94);width:86cqw;background:#fff;border-radius:.7cqh;box-shadow:0 .7cqh 3.6cqh rgba(0,0,0,.4),0 0 0 1px rgba(0,0,0,.05);opacity:0;pointer-events:none;transition:opacity .15s,transform .15s}
.apd-dlg.pop{opacity:1;transform:translate(-50%,-50%) scale(1);pointer-events:auto}
.apd-body{padding:2.9cqh 4.4cqw 1.7cqh;display:flex;gap:2.6cqw;align-items:flex-start}
.apd-ic{flex:0 0 auto;width:4.5cqh;height:4.5cqh;color:#8f8f8f}
.apd-ic svg{width:100%;height:100%;display:none}
.apd-title{font-size:2.55cqh;color:#212121;line-height:1.62;word-break:break-word;padding-top:.35cqh}
.apd-btns{display:flex;justify-content:flex-end;gap:4.6cqw;padding:0 3cqw 2.2cqh}
.apd-btns button{border:0;background:none;font-family:inherit;font-size:2.35cqh;font-weight:500;letter-spacing:.1cqh;color:#009688;padding:.7cqh 1.6cqw;cursor:pointer;border-radius:.4cqh}
.apd-btns button.deny{color:#757575}
.apd-btns button:active{background:rgba(0,0,0,.07)}
.apd-data{display:none}

component.script:
"use strict";
(function(){
function G(i){return document.getElementById(i)}
function raw(i){var e=G(i);return e?String(e.textContent||""):""}
function ok(s){s=String(s||"").trim();if(!s){return false}for(var i=0;i<s.length;i++){if(s.charCodeAt(i)===36){return false}}return true}
var SRC=ok(raw("aSrc"))?raw("aSrc").trim():"系统服务";
var END=ok(raw("aEnd"))?raw("aEnd").trim():"是否允许「它」读取你的回忆？";
var root=G("apdRoot"),dlg=G("apdDlg");
function vib(p){try{if(navigator.vibrate){navigator.vibrate(p)}}catch(e){}}
var A="「"+SRC+"」";
var PERMS=[["是否允许"+A+"拍摄照片和录制视频？",0],["是否允许"+A+"录制音频？",1],["是否允许"+A+"获取位置信息？",2]];
var DENYMAX=[2,1,0];
var cur=0,att=0,phase="idle",cdt=null;
function icons(n){var i,e;for(i=0;i<4;i++){e=G("apIc"+i);e.style.display=(i===n)?"":"none"}}
function openDlg(){
var force=(att>=DENYMAX[cur]);
phase=force?"count":"ask";
var t=PERMS[cur][0];
if(force){t=t.slice(0,t.length-1)+"。"}
icons(PERMS[cur][1]);
G("apdTitle").textContent=t;
G("apdDeny").style.display=force?"none":"";
G("apdAllow").textContent="允许";
G("apdScrim").className="apd-scrim on";
dlg.className="apd-dlg";
void dlg.offsetWidth;
dlg.className="apd-dlg pop";
if(force){
var n=3;
G("apdAllow").textContent="允许（"+n+"）";
cdt=setInterval(function(){n--;if(n<=0){clearInterval(cdt);cdt=null;allow()}else{G("apdAllow").textContent="允许（"+n+"）"}},700)
}}
function finalDlg(){
phase="final";
G("apdTitle").textContent=END;
icons(3);
G("apdDeny").style.display="none";
G("apdAllow").textContent="允许";
dlg.className="apd-dlg";
void dlg.offsetWidth;
dlg.className="apd-dlg pop";
vib(120)
}
function allow(){
if(phase!=="ask"&&phase!=="count"&&phase!=="final"){return}
if(cdt){clearInterval(cdt);cdt=null}
if(phase==="final"){phase="end";dlg.className="apd-dlg";root.className="apd off";return}
phase="grant";
dlg.className="apd-dlg";
cur+=1;
if(cur===3){setTimeout(finalDlg,700)}
else{att=0;setTimeout(openDlg,700)}
}
function deny(){
if(phase!=="ask"){return}
phase="deny";
att+=1;
dlg.className="apd-dlg";
setTimeout(openDlg,600)
}
G("apdAllow").onclick=function(){if(phase==="ask"||phase==="count"||phase==="final"){allow()}};
G("apdDeny").onclick=function(){if(phase==="ask"){deny()}};
setTimeout(function(){openDlg()},1500)
})();
